class BotServiceClientSync(ConnectClientSync):
    """
    Service for managing and controlling Minecraft bots.
    Provides comprehensive APIs for bot monitoring, movement control,
    inventory management, and interaction with server dialogs.

    Permissions:
    - READ_BOT_INFO: Required for GetBotList, GetBotInfo, GetInventoryState,
                     RenderBotPov, GetDialog
    - CONTROL_BOTS: Required to start, stop, or restart bots
    - UPDATE_BOT_CONFIG: Required for persistent per-bot setting changes
    - CONTROL_BOT_ACTIONS: Required for live movement, inventory, and dialog actions

    Error Handling:
    - NOT_FOUND: Instance or bot does not exist
    - FAILED_PRECONDITION: Bot is not online or required game state is unavailable
    - INTERNAL: Unexpected server errors (check server logs for details)
    """
    def __init__(
        self,
        address: str,
        *,
        codec: Codec | None = _PROTO_BINARY_CODEC,
        protocol: ProtocolType = ProtocolType.CONNECT,
        accept_compression: Iterable[Compression] | None = None,
        send_compression: Compression | None = _GZIP_COMPRESSION,
        timeout_ms: int | None = None,
        read_max_bytes: int | None = None,
        interceptors: Iterable[InterceptorSync] = (),
        http_client: SyncClient | None = None,
    ) -> None:
        super().__init__(
            address=address,
            codec=codec,
            protocol=protocol,
            accept_compression=accept_compression,
            send_compression=send_compression,
            timeout_ms=timeout_ms,
            read_max_bytes=read_max_bytes,
            interceptors=interceptors,
            http_client=http_client,
        )
    def set_bots_desired_state(
        self,
        request: SetBotsDesiredStateRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> SetBotsDesiredStateResponse:
        """
        Persists whether the selected bots should be running or stopped.
        The request returns after the desired state is durable. Connections are
        reconciled asynchronously and can be observed through WatchBotStatuses.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetBotsDesiredState",
                service_name="soulfire.v1.BotService",
                input=SetBotsDesiredStateRequest,
                output=SetBotsDesiredStateResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def restart_bots(
        self,
        request: RestartBotsRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> RestartBotsResponse:
        """
        Forces the selected bots to establish fresh connections.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="RestartBots",
                service_name="soulfire.v1.BotService",
                input=RestartBotsRequest,
                output=RestartBotsResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def watch_bot_statuses(
        self,
        request: WatchBotStatusesRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> Iterator[WatchBotStatusesResponse]:
        """
        Streams an initial snapshot followed by desired and runtime state changes.
        """
        return self.execute_server_stream(
            request=request,
            method=MethodInfo(
                name="WatchBotStatuses",
                service_name="soulfire.v1.BotService",
                input=WatchBotStatusesRequest,
                output=WatchBotStatusesResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.SERVER_STREAM,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def get_bot_list(
        self,
        request: BotListRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> BotListResponse:
        """
        Returns a list of all bots configured in the specified instance.
        Includes both online and offline bots with their current status.
        For online bots, includes live state (position, health, etc.) but NOT full inventory data.
        Requires READ_BOT_INFO permission.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetBotList",
                service_name="soulfire.v1.BotService",
                input=BotListRequest,
                output=BotListResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def get_bot_info(
        self,
        request: BotInfoRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> BotInfoResponse:
        """
        Returns detailed information about a specific bot.
        Includes full live state with complete inventory data when the bot is online.
        Requires READ_BOT_INFO permission.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetBotInfo",
                service_name="soulfire.v1.BotService",
                input=BotInfoRequest,
                output=BotInfoResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def update_bot_config_entry(
        self,
        request: BotUpdateConfigEntryRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> BotUpdateConfigEntryResponse:
        """
        Updates a single configuration entry for a specific bot.
        The configuration is persisted to the database immediately.
        Requires UPDATE_BOT_CONFIG permission.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="UpdateBotConfigEntry",
                service_name="soulfire.v1.BotService",
                input=BotUpdateConfigEntryRequest,
                output=BotUpdateConfigEntryResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def delete_bot_config_entry(
        self,
        request: BotDeleteConfigEntryRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> BotDeleteConfigEntryResponse:
        """
        Removes one bot override without replacing account settings or metadata.
        Repeated requests succeed when the override is already absent.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="DeleteBotConfigEntry",
                service_name="soulfire.v1.BotService",
                input=BotDeleteConfigEntryRequest,
                output=BotDeleteConfigEntryResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def render_bot_pov(
        self,
        request: BotRenderPovRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> BotRenderPovResponse:
        """
        Renders the bot's point-of-view as a PNG image using headless Vulkan.
        The bot must be online with a valid player and level.
        Uses the bot's current render distance setting.
        Requires READ_BOT_INFO permission.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="RenderBotPov",
                service_name="soulfire.v1.BotService",
                input=BotRenderPovRequest,
                output=BotRenderPovResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.UNARY,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def watch_bot_pov(
        self,
        request: BotWatchPovRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None,
        timeout_ms: int | None = None,
    ) -> Iterator[BotPovFrame]:
        """
        Streams rendered POV frames. Slow consumers receive the newest available
        frame and an explicit dropped-frame count instead of an unbounded backlog.
        """
        return self.execute_server_stream(
            request=request,
            method=MethodInfo(
                name="WatchBotPov",
                service_name="soulfire.v1.BotService",
                input=BotWatchPovRequest,
                output=BotPovFrame,
                idempotency_level=IdempotencyLevel.UNKNOWN,
                stream_type=StreamType.SERVER_STREAM,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
